            cwd: pollRequest.cwd,
            env: { ...pollRequest.env },
            executable: pollRequest.executable,
            observedAt,
            timeoutMs: this.terminalTimeoutMs,
        };

        return this.terminalPoll(request, {
            registerAbort: (abort) => {
                this.abortTerminalPoll = abort;
            },
        });
    }
}

